127	/// 小游戏完成结果的全局存储。
128	///
129	/// 游戏 iframe 通过 fetch `/__game_complete?result=xxx` 写入，
130	/// `MinigameOverlay` 轮询读取。
131	pub static GAME_COMPLETE_RESULT: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);
132	
133	#[expect(
134	    clippy::unwrap_used,
135	    reason = "Response builder infallible with known-good headers"
136	)]
137	#[expect(
138	    clippy::needless_pass_by_value,
139	    reason = "Signature required by Dioxus custom protocol API"
140	)]
141	fn ring_asset_handler(
142	    _id: dioxus::desktop::wry::WebViewId,
143	    request: http::Request<Vec<u8>>,
144	) -> http::Response<Cow<'static, [u8]>> {
145	    let uri = request.uri().to_string();
146	    let raw_path = request.uri().path();
147	    let path_clean = percent_decode(raw_path.trim_start_matches('/'));
148	
149	    // ── 小游戏完成端点（iframe 导航触发） ──
150	    if path_clean.starts_with("__game_complete") {
151	        let query = request.uri().query().unwrap_or("");
152	        let result = query
153	            .split('&')
154	            .find_map(|kv| {
155	                let (k, v) = kv.split_once('=')?;
156	                (k == "result").then(|| percent_decode(v))
157	            })
158	            .unwrap_or_default();
159	        tracing::debug!(result = %result, "game complete via ring-asset");
160	        if let Ok(mut slot) = GAME_COMPLETE_RESULT.lock() {
161	            *slot = Some(result);
162	        }
163	        // 纯黑空页面，与覆盖层背景一致，无视觉闪烁
164	        let body = br#"<!DOCTYPE html><html><body style="background:#000;margin:0"></body></html>"#;
165	        return http::Response::builder()
166	            .status(200)
167	            .header("Content-Type", "text/html")
168	            .body(Cow::from(body.to_vec()))
169	            .unwrap();
170	    }
171	
172	    // ── 虚拟 engine-sdk.js（兼容游戏显式 <script src="../../engine-sdk.js"> 加载） ──
173	    if path_clean == "engine-sdk.js" {
174	        return http::Response::builder()
175	            .status(200)
176	            .header("Content-Type", "application/javascript")
177	            .header("Access-Control-Allow-Origin", "*")
178	            .body(Cow::from(GAME_ENGINE_SDK_JS.as_bytes().to_vec()))
179	            .unwrap();
180	    }
181	
182	    let logical_path = LogicalPath::new(&path_clean);
183	
184	    tracing::debug!(uri = %uri, path = %logical_path, "ring-asset request");
185	
186	    #[expect(
187	        clippy::expect_used,
188	        reason = "uninitialised RM is an engine invariant violation"
189	    )]
190	    let rm = RESOURCE_MANAGER
191	        .get()
192	        .expect("invariant: ResourceManager not yet initialized when ring-asset request arrived");
193	
194	    let mime = guess_mime(&path_clean);
195	
196	    match rm.read_bytes(&logical_path) {
197	        Ok(bytes) => {
198	            // games/*/**.html: 自动注入 engine JS SDK（postMessage 桥接）
199	            let body = if path_clean.starts_with("games/") && mime == "text/html" {
200	                let html = String::from_utf8_lossy(&bytes);
201	                let injected = inject_engine_sdk(&html);
202	                Cow::from(injected.into_bytes())
203	            } else {
204	                Cow::from(bytes)
205	            };
206	            http::Response::builder()
207	                .status(200)
208	                .header("Content-Type", mime)
209	                .header("Access-Control-Allow-Origin", "*")
210	                .body(body)
211	                .unwrap()
212	        }
213	        Err(e) => {
214	            tracing::warn!(path = %logical_path, error = %e, "ring-asset 404");
215	            http::Response::builder()
216	                .status(404)
217	                .header("Content-Type", "text/plain")
218	                .body(Cow::from(format!("Not Found: {logical_path}").into_bytes()))
219	                .unwrap()
220	        }
221	    }
222	}
