224	#[expect(
225	    clippy::string_slice,
226	    reason = "slicing ASCII hex pairs at verified byte boundaries"
227	)]
228	fn percent_decode(input: &str) -> String {
229	    let mut out = Vec::with_capacity(input.len());
230	    let bytes = input.as_bytes();
231	    let mut i = 0;
232	    while i < bytes.len() {
233	        if bytes[i] == b'%'
234	            && i + 2 < bytes.len()
235	            && let Ok(byte) = u8::from_str_radix(&input[i + 1..i + 3], 16)
236	        {
237	            out.push(byte);
238	            i += 3;
239	            continue;
240	        }
241	        out.push(bytes[i]);
242	        i += 1;
243	    }
244	    String::from_utf8(out).unwrap_or_else(|_| input.to_string())
245	}
