247	fn guess_mime(path: &str) -> &'static str {
248	    match path.rsplit('.').next().unwrap_or("") {
249	        "jpg" | "jpeg" => "image/jpeg",
250	        "png" => "image/png",
251	        "webp" => "image/webp",
252	        "gif" => "image/gif",
253	        "svg" => "image/svg+xml",
254	        "webm" => "video/webm",
255	        "mp4" => "video/mp4",
256	        "mp3" => "audio/mpeg",
257	        "ogg" => "audio/ogg",
258	        "wav" => "audio/wav",
259	        "flac" => "audio/flac",
260	        "css" => "text/css",
261	        "js" => "application/javascript",
262	        "json" => "application/json",
263	        "html" => "text/html",
264	        _ => "application/octet-stream",
265	    }
266	}
