272	/// 向游戏 HTML 注入 engine JS SDK。
273	///
274	/// 在 `<head>` 标签后（或文档开头）插入 SDK script。
275	/// SDK 通过 `window.parent.postMessage` 与宿主通信。
276	#[expect(
277	    clippy::string_slice,
278	    reason = "slicing at positions derived from str::find, always char boundaries"
279	)]
280	fn inject_engine_sdk(html: &str) -> String {
281	    let sdk_tag = format!("<script>{GAME_ENGINE_SDK_JS}</script>");
282	    // 在 <head> 后注入，如果没有 <head> 则在开头注入
283	    if let Some(pos) = html.find("<head>") {
284	        let insert_pos = pos + "<head>".len();
285	        format!("{}{sdk_tag}{}", &html[..insert_pos], &html[insert_pos..])
286	    } else if let Some(pos) = html.find("<HEAD>") {
287	        let insert_pos = pos + "<HEAD>".len();
288	        format!("{}{sdk_tag}{}", &html[..insert_pos], &html[insert_pos..])
289	    } else {
290	        format!("{sdk_tag}{html}")
291	    }
292	}
