294	/// 同源 fetch-based engine JS SDK。
295	///
296	/// 提供与旧 host HTTP Bridge SDK 兼容的 `window.engine.*` API，
297	/// 内部使用同源 fetch 到 `ring-asset` handler 的虚拟端点通信。
298	///
299	/// 关键路径：`engine.complete(result)` → fetch `/__game_complete?result=xxx`
300	/// → ring-asset handler 存入 static → Rust 轮询读取。
301	const GAME_ENGINE_SDK_JS: &str = r#"
302	(function() {
303	    if (window.engine) return;
304	    window.engine = {
305	        complete: function(result) {
306	            var r = result !== undefined && result !== null ? String(result) : "";
307	            window.location.href = "/__game_complete?result=" + encodeURIComponent(r);
308	        },
309	        onComplete: function(result) {
310	            window.engine.complete(result);
311	        },
312	        playSound: function(name) {
313	            console.log("[engine SDK] playSound: " + name);
314	        },
315	        playBGM: function(name, shouldLoop) {
316	            console.log("[engine SDK] playBGM: " + name);
317	        },
318	        stopBGM: function() {
319	            console.log("[engine SDK] stopBGM");
320	        },
321	        getState: function(key) {
322	            console.warn("[engine SDK] getState not yet supported in iframe mode");
323	            return Promise.resolve(undefined);
324	        },
325	        setState: function(key, value) {
326	            console.warn("[engine SDK] setState not yet supported in iframe mode");
327	            return Promise.resolve();
328	        },
329	        log: function(level, message) {
330	            console.log("[game:" + level + "] " + message);
331	        }
332	    };
333	
334	    // 旧 API 兼容：window.ipc.postMessage 映射
335	    if (!window.ipc) {
336	        window.ipc = {
337	            postMessage: function(jsonStr) {
338	                try {
339	                    var msg = JSON.parse(jsonStr);
340	                    if (msg.type === "onComplete") {
341	                        window.engine.complete(msg.result || msg.data);
342	                    }
343	                } catch(e) {}
344	            }
345	        };
346	    }
347	})();
348	"#;
