362	// Screenshot bridge (debug server ↔ WebView)
363	// ---------------------------------------------------------------------------
364	
365	/// 接收来自 debug HTTP server 的截图请求，通过 `document::eval()` 在 `WebView` 中
366	/// 执行 JS 截图代码，将结果通过 oneshot 通道回传。
367	#[cfg(not(target_arch = "wasm32"))]
368	async fn screenshot_bridge(mut rx: tokio::sync::mpsc::Receiver<debug_server::ScreenshotRequest>) {
369	    while let Some(req) = rx.recv().await {
370	        // 每个请求启动独立 eval，避免阻塞后续请求
371	        spawn(async move {
372	            let mut eval = document::eval(debug_server::SCREENSHOT_JS);
373	            match eval.recv().await {
374	                Ok(msg) => {
375	                    let result: serde_json::Value = msg;
376	                    if let Some(err) = result.get("error").and_then(|v| v.as_str()) {
377	                        // receiver 可能已因超时而被丢弃，忽略发送失败
378	                        let _ = req.reply.send(Err(err.to_string()));
379	                    } else {
380	                        let width = result
381	                            .get("width")
382	                            .and_then(serde_json::Value::as_u64)
383	                            .unwrap_or(1920) as u32;
384	                        let height = result
385	                            .get("height")
386	                            .and_then(serde_json::Value::as_u64)
387	                            .unwrap_or(1080) as u32;
388	                        let data = result
389	                            .get("data")
390	                            .and_then(|v| v.as_str())
391	                            .unwrap_or("")
392	                            .to_string();
393	                        // receiver 可能已因超时而被丢弃，忽略发送失败
394	                        let _ = req.reply.send(Ok(debug_server::ScreenshotData {
395	                            format: "png".to_string(),
396	                            width,
397	                            height,
398	                            data_base64: data,
399	                        }));
400	                    }
401	                }
402	                Err(e) => {
403	                    // receiver 可能已因超时而被丢弃，忽略发送失败
404	                    let _ = req.reply.send(Err(format!("eval 失败: {e}")));
405	                }
406	            }
407	        });
408	    }
409	}
