415	fn App() -> Element {
416	    // 全局 AppState：Arc<Mutex<AppStateInner>>
417	    let app_state = use_context_provider(|| AppState {
418	        inner: Arc::new(Mutex::new(AppStateInner::new())),
419	    });
420	
421	    // 确认弹窗状态（全局 Signal，各页面共享）
422	    let _pending_confirm: Signal<Option<PendingConfirm>> =
423	        use_context_provider(|| Signal::new(None));
424	
425	    // Toast 队列（全局 Signal）
426	    let _toast_queue: Signal<ToastQueue> =
427	        use_context_provider(|| Signal::new(ToastQueue::default()));
428	
429	    // 初始化阶段
430	    let mut init_phase = use_signal(|| InitPhase::Loading);
431	
432	    // RenderState signal：tick loop 每帧更新
433	    let mut render_state = use_signal(RenderState::new);
434	
435	    // 初始化后端子系统（仅首次 mount）
436	    let app_state_init = app_state.clone();
437	    #[expect(
438	        clippy::expect_used,
439	        reason = "Mutex poison means engine panicked; we want to propagate"
440	    )]
441	    use_hook(move || {
442	        spawn(async move {
443	            let result = {
444	                let mut inner = app_state_init
445	                    .inner
446	                    .lock()
447	                    .expect("invariant: app state mutex not poisoned");
448	                init::initialize_inner(&mut inner)
449	            };
450	            match result {
451	                Ok(()) => {
452	                    {
453	                        let mut inner = app_state_init
454	                            .inner
455	                            .lock()
456	                            .expect("invariant: app state mutex not poisoned");
457	                        inner.frontend_connected(Some("dioxus-desktop".to_string()));
458	                    }
459	                    #[cfg(not(target_arch = "wasm32"))]
460	                    {
461	                        let debug_port = {
462	                            let inner = app_state_init
463	                                .inner
464	                                .lock()
465	                                .expect("invariant: app state mutex not poisoned");
466	                            inner
467	                                .services
468	                                .as_ref()
469	                                .and_then(|s| s.config.debug.resolve_debug_server())
470	                        };
471	                        if let Some(port) = debug_port {
472	                            let (screenshot_tx, screenshot_rx) = debug_server::screenshot_channel();
473	                            let app_for_debug = app_state_init.clone();
474	                            spawn(async move {
475	                                debug_server::run(app_for_debug, port, screenshot_tx).await;
476	                            });
477	                            spawn(screenshot_bridge(screenshot_rx));
478	                        }
479	                    }
480	                    info!("后端初始化完成");
481	                    init_phase.set(InitPhase::Ready);
482	                }
483	                Err(e) => {
484	                    error!(error = %e, "后端初始化失败");
485	                    init_phase.set(InitPhase::Error(e.to_string()));
486	                }
487	            }
488	        });
489	    });
490	
491	    // Tick loop：~30 FPS
492	    let app_state_tick = app_state.clone();
493	    use_hook(move || {
494	        spawn(async move {
495	            loop {
496	                tokio::time::sleep(Duration::from_millis(33)).await;
497	                if let Ok(mut inner) = app_state_tick.inner.lock() {
498	                    inner.process_tick(1.0 / 30.0);
499	                    render_state.set(inner.render_state.clone());
500	                }
501	            }
502	        });
503	    });
504	
505	    // 键盘绑定：JS 监听 → dioxus.send() → Rust recv() 处理
506	    let app_state_keys = app_state.clone();
507	    use_hook(move || {
508	        spawn(async move {
509	            let mut eval = document::eval(
510	                r#"
511	                document.addEventListener("keydown", function(e) {
512	                    dioxus.send({ type: "down", key: e.key, code: e.code });
513	                    if (["Escape", " ", "Enter", "Control", "Backspace"].includes(e.key)) {
514	                        e.preventDefault();
515	                    }
516	                });
517	                document.addEventListener("keyup", function(e) {
518	                    dioxus.send({ type: "up", key: e.key, code: e.code });
519	                });
520	                "#,
521	            );
522	
523	            loop {
524	                let msg: Result<serde_json::Value, _> = eval.recv().await;
525	                let Ok(msg) = msg else { break };
526	
527	                let event_type = msg.get("type").and_then(|v| v.as_str()).unwrap_or("");
528	                let key = msg.get("key").and_then(|v| v.as_str()).unwrap_or("");
529	
530	                if let Ok(mut inner) = app_state_keys.inner.lock() {
531	                    match (event_type, key) {
532	                        ("down", "Escape") => {
533	                            let screen = inner.render_state.host_screen.clone();
534	                            match screen {
535	                                HostScreen::InGame => {
536	                                    inner.set_host_screen(HostScreen::InGameMenu);
537	                                }
538	                                HostScreen::InGameMenu
