#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
#![allow(
    non_snake_case,
    reason = "Dioxus components use PascalCase by convention"
)]

// ── 后端模块 ──
pub mod audio;
pub mod command_executor;
pub mod config;
pub mod error;
pub mod init;
pub mod layout_config;
pub mod manifest;
pub mod map_data;
